-- big late leaf + a phrase rare in it, page 1, sort -updatedAt
-- cost variable: hits = 0 (scales with products)
SELECT p.id, p.name, p.tax_class, p.updated_at FROM catalog_product p WHERE p.name ILIKE '%bagażnik%' AND (p.primary_category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/fb2be761-1a8c-5d94-9c3f-2917db623644/a2f9bd8c-5f9d-58ae-a2d8-645f1736acbb/ef462a66-fe55-50aa-99b1-36061187ca88/%') OR EXISTS (SELECT 1 FROM catalog_product_category pc WHERE pc.product_id = p.id AND pc.category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/fb2be761-1a8c-5d94-9c3f-2917db623644/a2f9bd8c-5f9d-58ae-a2d8-645f1736acbb/ef462a66-fe55-50aa-99b1-36061187ca88/%'))) ORDER BY p.updated_at DESC, p.id DESC LIMIT 26;
